const plans={"驼背纠正训练计划.html": "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover\">\n<title>驼背纠正训练计划</title>\n<style>\n:root{\n  --bg:#0a0e13; --bg2:#111820; --card:#161e27; --card2:#1b242f;\n  --border:#242f3d; --border2:#2e3b4c;\n  --text:#e9eff6; --muted:#8697a8; --muted2:#5f7183;\n  --accent:#00e0a4; --accent2:#00b884;\n  --warn:#ff9f43; --warnbg:rgba(255,159,67,.10);\n  --danger:#ff5f6d; --good:#00e0a4;\n}\n*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}\nhtml,body{height:100%}\nbody{\n  background:var(--bg); color:var(--text);\n  font-family:-apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",sans-serif;\n  font-size:15px; line-height:1.6; overflow:hidden;\n  -webkit-font-smoothing:antialiased;\n}\n#app{display:flex;flex-direction:column;height:100%;max-width:560px;margin:0 auto;\n  background:linear-gradient(170deg,#0a0e13 0%,#111a24 100%);position:relative}\n\n/* ===== 顶栏 ===== */\n.topbar{padding:14px 18px 12px;border-bottom:1px solid var(--border);flex-shrink:0}\n.tb-row{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:9px}\n.tb-title{font-size:16px;font-weight:700;letter-spacing:.3px}\n.tb-meta{font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums}\n.tb-meta b{color:var(--accent);font-weight:700}\n.progress{height:3px;background:var(--border);border-radius:2px;overflow:hidden}\n.progress-fill{height:100%;width:0;background:linear-gradient(90deg,var(--accent2),var(--accent));\n  border-radius:2px;transition:width .35s cubic-bezier(.4,0,.2,1)}\n\n/* ===== 内容区 ===== */\n.content{flex:1;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch;\n  padding:18px 18px 24px;scroll-behavior:smooth}\n.content::-webkit-scrollbar{width:0}\n.page{animation:pageIn .32s cubic-bezier(.4,0,.2,1)}\n@keyframes pageIn{from{opacity:0;transform:translateX(14px)}to{opacity:1;transform:none}}\n\n/* ===== 通用卡片 ===== */\n.card{background:var(--card);border:1px solid var(--border);border-radius:14px;\n  padding:16px;margin-bottom:14px}\n.card-hd{display:flex;align-items:center;gap:10px;margin-bottom:12px}\n.card-ico{width:30px;height:30px;border-radius:9px;display:flex;align-items:center;justify-content:center;\n  font-size:15px;font-weight:700;flex-shrink:0;background:rgba(0,224,164,.13);color:var(--accent)}\n.card-t{font-size:15px;font-weight:700}\n\n.sec-t{font-size:11px;font-weight:700;letter-spacing:1.4px;color:var(--muted2);\n  text-transform:uppercase;margin:16px 0 9px}\n\n/* ===== 封面 ===== */\n.cover-hero{padding:6px 0 18px;text-align:center}\n.cover-hero h1{font-size:26px;font-weight:800;letter-spacing:-.5px;margin-bottom:8px;\n  background:linear-gradient(120deg,#fff 20%,var(--accent));-webkit-background-clip:text;\n  -webkit-text-fill-color:transparent;background-clip:text}\n.cover-hero p{font-size:13px;color:var(--muted);line-height:1.7}\n\n/* 首页高亮提示横幅 */\n.big-banner{margin:4px 0 16px;padding:14px 16px;border-radius:14px;\n  background:linear-gradient(120deg,rgba(255,159,67,.16),rgba(0,224,164,.14));\n  border:1.5px solid rgba(255,159,67,.55);box-shadow:0 6px 18px rgba(255,159,67,.12)}\n.big-banner .bb-k{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:800;\n  letter-spacing:1px;color:#ff9f43;margin-bottom:8px}\n.big-banner .bb-k::before{content:\"⚡\";font-size:14px}\n.big-banner .bb-row{display:flex;gap:10px;flex-wrap:wrap}\n.big-banner .bb-item{flex:1;min-width:120px;background:rgba(10,14,19,.45);border-radius:10px;\n  padding:10px 11px;border:1px solid var(--border)}\n.big-banner .bb-t{font-size:15px;font-weight:800;color:#fff;margin-bottom:3px}\n.big-banner .bb-t b{color:var(--accent)}\n.big-banner .bb-d{font-size:11.5px;line-height:1.6;color:#c4d0dc}\n\n.timebar{display:flex;height:44px;border-radius:11px;overflow:hidden;margin-bottom:9px;\n  border:1px solid var(--border)}\n.tb-seg{display:flex;flex-direction:column;align-items:center;justify-content:center;\n  font-size:11px;line-height:1.25;color:#0a0e13;font-weight:700}\n.tb-seg span{font-size:9px;font-weight:600;opacity:.75}\n.tb-legend{display:flex;gap:14px;justify-content:center;font-size:11px;color:var(--muted);margin-bottom:4px}\n.tb-legend i{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:5px;vertical-align:middle}\n\n.kv{display:grid;grid-template-columns:1fr 1fr;gap:9px}\n.kv-item{background:var(--card2);border:1px solid var(--border);border-radius:10px;padding:11px 12px}\n.kv-k{font-size:10px;color:var(--muted2);letter-spacing:.8px;font-weight:700;margin-bottom:3px}\n.kv-v{font-size:15px;font-weight:700;font-variant-numeric:tabular-nums}\n.kv-v small{font-size:11px;color:var(--muted);font-weight:600}\n\n.ov-list{display:flex;flex-direction:column;gap:7px}\n.ov-item{display:flex;align-items:center;gap:11px;background:var(--card2);\n  border:1px solid var(--border);border-radius:10px;padding:10px 12px;cursor:pointer;\n  transition:border-color .2s,transform .15s}\n.ov-item:active{transform:scale(.985)}\n.ov-item:hover{border-color:var(--border2)}\n.ov-n{width:22px;height:22px;border-radius:7px;background:rgba(0,224,164,.13);color:var(--accent);\n  font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.ov-name{flex:1;font-size:13px;font-weight:600}\n.ov-s{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}\n\n/* ===== 动作页 ===== */\n.ex-head{display:flex;align-items:flex-start;gap:12px;margin-bottom:14px}\n.ex-idx{width:38px;height:38px;border-radius:11px;background:rgba(0,224,164,.13);\n  color:var(--accent);display:flex;align-items:center;justify-content:center;\n  font-size:15px;font-weight:800;flex-shrink:0}\n.ex-title{flex:1;min-width:0}\n.ex-title h2{font-size:19px;font-weight:800;letter-spacing:-.3px;line-height:1.3}\n.ex-en{font-size:11px;color:var(--muted2);letter-spacing:.5px;margin-top:2px}\n.ex-target{font-size:11px;color:var(--accent);margin-top:5px;font-weight:600}\n\n.specs{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:14px}\n.spec{background:var(--card2);border:1px solid var(--border);border-radius:10px;\n  padding:9px 6px;text-align:center}\n.spec-v{font-size:16px;font-weight:800;font-variant-numeric:tabular-nums;line-height:1.2}\n.spec-k{font-size:9.5px;color:var(--muted2);letter-spacing:.7px;font-weight:700;margin-top:3px}\n\n.setup{background:var(--bg2);border:1px solid var(--border);border-radius:10px;\n  padding:11px 13px;margin-bottom:13px;font-size:12.5px;color:#c4d0dc;line-height:1.65}\n.setup b{color:var(--text);font-weight:700}\n\n/* 动作示意图 */\n.ex-fig{background:var(--bg2);border:1px solid var(--border);border-radius:12px;\n  padding:6px 6px 2px;margin-bottom:13px;display:flex;justify-content:center}\n.ex-fig svg{width:100%;max-width:320px;height:auto;display:block}\n\n.steps{counter-reset:s;margin-bottom:13px}\n.step{display:flex;gap:10px;margin-bottom:8px}\n.step-n{width:20px;height:20px;border-radius:6px;background:var(--border);color:var(--muted);\n  font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;\n  flex-shrink:0;margin-top:1px}\n.step-t{font-size:13px;color:#c4d0dc;line-height:1.6}\n\n/* 注意点 */\n.notes{background:var(--warnbg);border:1px solid rgba(255,159,67,.28);border-radius:12px;\n  padding:13px 14px;margin-bottom:14px}\n.notes-hd{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:800;\n  color:var(--warn);letter-spacing:.8px;margin-bottom:9px}\n.note{display:flex;gap:9px;margin-bottom:7px;font-size:12.5px;line-height:1.6;color:#e2d3c2}\n.note:last-child{margin-bottom:0}\n.note-d{color:var(--warn);font-weight:800;flex-shrink:0;font-size:13px;line-height:1.5}\n.note b{color:#ffc78b;font-weight:700}\n\n/* 危险警示 */\n.alert{background:rgba(255,95,109,.09);border:1px solid rgba(255,95,109,.32);\n  border-radius:12px;padding:13px 14px;margin-bottom:14px}\n.alert-hd{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:800;\n  color:var(--danger);letter-spacing:.8px;margin-bottom:10px}\n.alert-row{display:flex;gap:9px;margin-bottom:8px;font-size:12.5px;line-height:1.6}\n.alert-row:last-child{margin-bottom:0}\n.alert-b{width:19px;height:19px;border-radius:5px;display:flex;align-items:center;\n  justify-content:center;font-size:11px;font-weight:800;flex-shrink:0;margin-top:1px}\n.alert-ok{background:rgba(0,224,164,.18);color:var(--accent)}\n.alert-no{background:rgba(255,95,109,.18);color:var(--danger)}\n.alert-t{flex:1;color:#d5dde5}\n.alert-t b{color:#fff;font-weight:700}\n\n/* 组打卡 */\n.sets-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}\n.sets-hd-t{font-size:11px;font-weight:700;letter-spacing:1.2px;color:var(--muted2)}\n.sets-cnt{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}\n.sets{display:flex;gap:9px;margin-bottom:13px}\n.set-dot{flex:1;height:46px;border-radius:11px;background:var(--card2);\n  border:1.5px solid var(--border);display:flex;flex-direction:column;align-items:center;\n  justify-content:center;gap:2px;cursor:pointer;transition:all .2s;position:relative}\n.set-dot:active{transform:scale(.94)}\n.set-num{font-size:13px;font-weight:800;color:var(--muted2);font-variant-numeric:tabular-nums}\n.set-reps{font-size:9.5px;color:var(--muted2);letter-spacing:.3px}\n.set-dot.done{background:rgba(0,224,164,.13);border-color:var(--accent)}\n.set-dot.done .set-num,.set-dot.done .set-reps{color:var(--accent)}\n\n/* 计时器 */\n.timer{background:var(--card2);border:1px solid var(--border);border-radius:12px;\n  padding:13px 14px;display:flex;align-items:center;gap:13px}\n.tm-main{flex:1;min-width:0}\n.tm-disp{display:flex;align-items:baseline;gap:5px;margin-bottom:3px}\n.tm-sec{font-size:29px;font-weight:800;font-variant-numeric:tabular-nums;line-height:1;\n  letter-spacing:-1px}\n.tm-sec.run{color:var(--accent)}\n.tm-sec.fin{color:var(--warn)}\n.tm-unit{font-size:11px;color:var(--muted2);font-weight:600}\n.tm-hint{font-size:10.5px;color:var(--muted2);line-height:1.5;height:16px;overflow:hidden;\n  text-overflow:ellipsis;white-space:nowrap}\n.tm-ctrls{display:flex;flex-direction:column;gap:6px;flex-shrink:0}\n.tm-row{display:flex;gap:6px}\n.tm-btn{border:1px solid var(--border);background:var(--bg2);color:var(--text);\n  border-radius:8px;font-size:11px;font-weight:700;cursor:pointer;transition:all .18s;\n  font-family:inherit}\n.tm-btn:active{transform:scale(.93)}\n.tm-btn:hover{border-color:var(--border2)}\n.tm-adj{width:32px;height:28px}\n.tm-play{width:60px;height:28px;background:rgba(0,224,164,.13);color:var(--accent);\n  border-color:rgba(0,224,164,.3)}\n.tm-play.on{background:rgba(255,159,67,.13);color:var(--warn);border-color:rgba(255,159,67,.3)}\n.tm-reset{width:100%;height:26px;font-size:10.5px;color:var(--muted)}\n\n/* 清单页 */\n.chk{display:flex;align-items:flex-start;gap:11px;padding:11px 0;border-bottom:1px solid var(--border)}\n.chk:last-child{border-bottom:none;padding-bottom:0}\n.chk-b{width:22px;height:22px;border-radius:7px;border:1.5px solid var(--border2);\n  background:var(--bg2);flex-shrink:0;cursor:pointer;display:flex;align-items:center;\n  justify-content:center;transition:all .2s;margin-top:1px}\n.chk-b:active{transform:scale(.88)}\n.chk.done .chk-b{background:var(--accent);border-color:var(--accent)}\n.chk-b svg{width:12px;height:12px;stroke:#0a0e13;stroke-width:3.2;fill:none;opacity:0;transition:opacity .2s}\n.chk.done .chk-b svg{opacity:1}\n.chk-t{flex:1;min-width:0}\n.chk-name{font-size:13.5px;font-weight:600;line-height:1.4}\n.chk.done .chk-name{color:var(--muted2);text-decoration:line-through}\n.chk-det{font-size:11.5px;color:var(--muted);margin-top:2px;line-height:1.5}\n.chk-dose{font-size:11px;color:var(--muted2);font-variant-numeric:tabular-nums;flex-shrink:0;\n  margin-top:2px}\n\n.tip{background:var(--bg2);border-left:2.5px solid var(--accent);border-radius:0 9px 9px 0;\n  padding:10px 13px;font-size:12.5px;color:#c4d0dc;line-height:1.65;margin-top:12px}\n.tip b{color:var(--text);font-weight:700}\n\n/* 完成页 */\n.done-hero{text-align:center;padding:22px 0 18px}\n.done-ico{width:62px;height:62px;border-radius:50%;background:rgba(0,224,164,.13);\n  color:var(--accent);display:flex;align-items:center;justify-content:center;margin:0 auto 14px}\n.done-hero h2{font-size:21px;font-weight:800;margin-bottom:6px}\n.done-hero p{font-size:13px;color:var(--muted)}\n.done-stat{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-bottom:14px}\n\n/* ===== 底部导航 ===== */\n.nav{flex-shrink:0;padding:11px 18px calc(11px + env(safe-area-inset-bottom));\n  border-top:1px solid var(--border);display:flex;align-items:center;gap:12px;\n  background:rgba(10,14,19,.94);backdrop-filter:blur(12px)}\n.nav-btn{flex:0 0 auto;min-width:76px;height:40px;border-radius:10px;border:1px solid var(--border);\n  background:var(--card);color:var(--text);font-size:13px;font-weight:700;cursor:pointer;\n  font-family:inherit;transition:all .18s;display:flex;align-items:center;justify-content:center;gap:5px}\n.nav-btn:active{transform:scale(.95)}\n.nav-btn:hover:not(:disabled){border-color:var(--border2);background:var(--card2)}\n.nav-btn:disabled{opacity:.32;cursor:not-allowed}\n.nav-btn.pri{background:rgba(0,224,164,.13);border-color:rgba(0,224,164,.3);color:var(--accent)}\n.dots{flex:1;display:flex;justify-content:center;gap:6px}\n.dot{width:6px;height:6px;border-radius:50%;background:var(--border2);cursor:pointer;\n  transition:all .25s;flex-shrink:0}\n.dot.on{width:18px;border-radius:3px;background:var(--accent)}\n.dot.seen{background:var(--muted)}\n\n@media(max-width:360px){\n  .specs{gap:6px}\n  .cover-hero h1{font-size:23px}\n  .ex-title h2{font-size:17px}\n  .nav-btn{min-width:66px;font-size:12px}\n}\n</style>\n</head>\n<body>\n<div id=\"app\">\n  <div class=\"topbar\">\n    <div class=\"tb-row\">\n      <div class=\"tb-title\" id=\"headTitle\">驼背纠正训练计划</div>\n      <div class=\"tb-meta\" id=\"headMeta\">0 / 18 组</div>\n    </div>\n    <div class=\"progress\"><div class=\"progress-fill\" id=\"progFill\"></div></div>\n  </div>\n\n  <div class=\"content\" id=\"content\"></div>\n\n  <div class=\"nav\">\n    <button class=\"nav-btn\" id=\"prevBtn\">&#8249; 上一页</button>\n    <div class=\"dots\" id=\"dots\"></div>\n    <button class=\"nav-btn pri\" id=\"nextBtn\">下一页 &#8250;</button>\n  </div>\n</div>\n\n<script src=\"__PLAN_SCRIPT_0__\"></script>\n</body>\n</html>\n", "综合练背训练计划.html": "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover\">\n<title>综合练背训练计划</title>\n<style>\n:root{\n  --bg:#0a0e13; --bg2:#111820; --card:#161e27; --card2:#1b242f;\n  --border:#242f3d; --border2:#2e3b4c;\n  --text:#e9eff6; --muted:#8697a8; --muted2:#5f7183;\n  --accent:#00e0a4; --accent2:#00b884;\n  --warn:#ff9f43; --warnbg:rgba(255,159,67,.10);\n  --danger:#ff5f6d; --good:#00e0a4;\n}\n*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}\nhtml,body{height:100%}\nbody{\n  background:var(--bg); color:var(--text);\n  font-family:-apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",sans-serif;\n  font-size:15px; line-height:1.6; overflow:hidden;\n  -webkit-font-smoothing:antialiased;\n}\n#app{display:flex;flex-direction:column;height:100%;max-width:560px;margin:0 auto;\n  background:linear-gradient(170deg,#0a0e13 0%,#111a24 100%);position:relative}\n\n/* ===== 顶栏 ===== */\n.topbar{padding:14px 18px 12px;border-bottom:1px solid var(--border);flex-shrink:0}\n.tb-row{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:9px}\n.tb-title{font-size:16px;font-weight:700;letter-spacing:.3px}\n.tb-meta{font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums}\n.tb-meta b{color:var(--accent);font-weight:700}\n.progress{height:3px;background:var(--border);border-radius:2px;overflow:hidden}\n.progress-fill{height:100%;width:0;background:linear-gradient(90deg,var(--accent2),var(--accent));\n  border-radius:2px;transition:width .35s cubic-bezier(.4,0,.2,1)}\n\n/* ===== 内容区 ===== */\n.content{flex:1;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch;\n  padding:18px 18px 24px;scroll-behavior:smooth}\n.content::-webkit-scrollbar{width:0}\n.page{animation:pageIn .32s cubic-bezier(.4,0,.2,1)}\n@keyframes pageIn{from{opacity:0;transform:translateX(14px)}to{opacity:1;transform:none}}\n\n/* ===== 通用卡片 ===== */\n.card{background:var(--card);border:1px solid var(--border);border-radius:14px;\n  padding:16px;margin-bottom:14px}\n.card-hd{display:flex;align-items:center;gap:10px;margin-bottom:12px}\n.card-ico{width:30px;height:30px;border-radius:9px;display:flex;align-items:center;justify-content:center;\n  font-size:15px;font-weight:700;flex-shrink:0;background:rgba(0,224,164,.13);color:var(--accent)}\n.card-t{font-size:15px;font-weight:700}\n\n.sec-t{font-size:11px;font-weight:700;letter-spacing:1.4px;color:var(--muted2);\n  text-transform:uppercase;margin:16px 0 9px}\n\n/* ===== 封面 ===== */\n.cover-hero{padding:6px 0 18px;text-align:center}\n.cover-hero h1{font-size:26px;font-weight:800;letter-spacing:-.5px;margin-bottom:8px;\n  background:linear-gradient(120deg,#fff 20%,var(--accent));-webkit-background-clip:text;\n  -webkit-text-fill-color:transparent;background-clip:text}\n.cover-hero p{font-size:13px;color:var(--muted);line-height:1.7}\n\n/* 首页高亮提示横幅 */\n.big-banner{margin:4px 0 16px;padding:14px 16px;border-radius:14px;\n  background:linear-gradient(120deg,rgba(255,159,67,.16),rgba(0,224,164,.14));\n  border:1.5px solid rgba(255,159,67,.55);box-shadow:0 6px 18px rgba(255,159,67,.12)}\n.big-banner .bb-k{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:800;\n  letter-spacing:1px;color:#ff9f43;margin-bottom:8px}\n.big-banner .bb-k::before{content:\"⚡\";font-size:14px}\n.big-banner .bb-row{display:flex;gap:10px;flex-wrap:wrap}\n.big-banner .bb-item{flex:1;min-width:120px;background:rgba(10,14,19,.45);border-radius:10px;\n  padding:10px 11px;border:1px solid var(--border)}\n.big-banner .bb-t{font-size:15px;font-weight:800;color:#fff;margin-bottom:3px}\n.big-banner .bb-t b{color:var(--accent)}\n.big-banner .bb-d{font-size:11.5px;line-height:1.6;color:#c4d0dc}\n\n.timebar{display:flex;height:44px;border-radius:11px;overflow:hidden;margin-bottom:9px;\n  border:1px solid var(--border)}\n.tb-seg{display:flex;flex-direction:column;align-items:center;justify-content:center;\n  font-size:11px;line-height:1.25;color:#0a0e13;font-weight:700}\n.tb-seg span{font-size:9px;font-weight:600;opacity:.75}\n.tb-legend{display:flex;gap:14px;justify-content:center;font-size:11px;color:var(--muted);margin-bottom:4px}\n.tb-legend i{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:5px;vertical-align:middle}\n\n.kv{display:grid;grid-template-columns:1fr 1fr;gap:9px}\n.kv-item{background:var(--card2);border:1px solid var(--border);border-radius:10px;padding:11px 12px}\n.kv-k{font-size:10px;color:var(--muted2);letter-spacing:.8px;font-weight:700;margin-bottom:3px}\n.kv-v{font-size:15px;font-weight:700;font-variant-numeric:tabular-nums}\n.kv-v small{font-size:11px;color:var(--muted);font-weight:600}\n\n.ov-list{display:flex;flex-direction:column;gap:7px}\n.ov-item{display:flex;align-items:center;gap:11px;background:var(--card2);\n  border:1px solid var(--border);border-radius:10px;padding:10px 12px;cursor:pointer;\n  transition:border-color .2s,transform .15s}\n.ov-item:active{transform:scale(.985)}\n.ov-item:hover{border-color:var(--border2)}\n.ov-n{width:22px;height:22px;border-radius:7px;background:rgba(0,224,164,.13);color:var(--accent);\n  font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.ov-name{flex:1;font-size:13px;font-weight:600}\n.ov-s{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}\n\n/* ===== 动作页 ===== */\n.ex-head{display:flex;align-items:flex-start;gap:12px;margin-bottom:14px}\n.ex-idx{width:38px;height:38px;border-radius:11px;background:rgba(0,224,164,.13);\n  color:var(--accent);display:flex;align-items:center;justify-content:center;\n  font-size:15px;font-weight:800;flex-shrink:0}\n.ex-title{flex:1;min-width:0}\n.ex-title h2{font-size:19px;font-weight:800;letter-spacing:-.3px;line-height:1.3}\n.ex-en{font-size:11px;color:var(--muted2);letter-spacing:.5px;margin-top:2px}\n.ex-target{font-size:11px;color:var(--accent);margin-top:5px;font-weight:600}\n\n.specs{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:14px}\n.spec{background:var(--card2);border:1px solid var(--border);border-radius:10px;\n  padding:9px 6px;text-align:center}\n.spec-v{font-size:16px;font-weight:800;font-variant-numeric:tabular-nums;line-height:1.2}\n.spec-k{font-size:9.5px;color:var(--muted2);letter-spacing:.7px;font-weight:700;margin-top:3px}\n\n.setup{background:var(--bg2);border:1px solid var(--border);border-radius:10px;\n  padding:11px 13px;margin-bottom:13px;font-size:12.5px;color:#c4d0dc;line-height:1.65}\n.setup b{color:var(--text);font-weight:700}\n\n/* 动作示意图 */\n.ex-fig{background:var(--bg2);border:1px solid var(--border);border-radius:12px;\n  padding:6px 6px 2px;margin-bottom:13px;display:flex;justify-content:center}\n.ex-fig svg{width:100%;max-width:320px;height:auto;display:block}\n\n.steps{counter-reset:s;margin-bottom:13px}\n.step{display:flex;gap:10px;margin-bottom:8px}\n.step-n{width:20px;height:20px;border-radius:6px;background:var(--border);color:var(--muted);\n  font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;\n  flex-shrink:0;margin-top:1px}\n.step-t{font-size:13px;color:#c4d0dc;line-height:1.6}\n\n/* 注意点 */\n.notes{background:var(--warnbg);border:1px solid rgba(255,159,67,.28);border-radius:12px;\n  padding:13px 14px;margin-bottom:14px}\n.notes-hd{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:800;\n  color:var(--warn);letter-spacing:.8px;margin-bottom:9px}\n.note{display:flex;gap:9px;margin-bottom:7px;font-size:12.5px;line-height:1.6;color:#e2d3c2}\n.note:last-child{margin-bottom:0}\n.note-d{color:var(--warn);font-weight:800;flex-shrink:0;font-size:13px;line-height:1.5}\n.note b{color:#ffc78b;font-weight:700}\n\n/* 危险警示 */\n.alert{background:rgba(255,95,109,.09);border:1px solid rgba(255,95,109,.32);\n  border-radius:12px;padding:13px 14px;margin-bottom:14px}\n.alert-hd{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:800;\n  color:var(--danger);letter-spacing:.8px;margin-bottom:10px}\n.alert-row{display:flex;gap:9px;margin-bottom:8px;font-size:12.5px;line-height:1.6}\n.alert-row:last-child{margin-bottom:0}\n.alert-b{width:19px;height:19px;border-radius:5px;display:flex;align-items:center;\n  justify-content:center;font-size:11px;font-weight:800;flex-shrink:0;margin-top:1px}\n.alert-ok{background:rgba(0,224,164,.18);color:var(--accent)}\n.alert-no{background:rgba(255,95,109,.18);color:var(--danger)}\n.alert-t{flex:1;color:#d5dde5}\n.alert-t b{color:#fff;font-weight:700}\n\n/* 组打卡 */\n.sets-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}\n.sets-hd-t{font-size:11px;font-weight:700;letter-spacing:1.2px;color:var(--muted2)}\n.sets-cnt{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}\n.sets{display:flex;gap:9px;margin-bottom:13px}\n.set-dot{flex:1;height:46px;border-radius:11px;background:var(--card2);\n  border:1.5px solid var(--border);display:flex;flex-direction:column;align-items:center;\n  justify-content:center;gap:2px;cursor:pointer;transition:all .2s;position:relative}\n.set-dot:active{transform:scale(.94)}\n.set-num{font-size:13px;font-weight:800;color:var(--muted2);font-variant-numeric:tabular-nums}\n.set-reps{font-size:9.5px;color:var(--muted2);letter-spacing:.3px}\n.set-dot.done{background:rgba(0,224,164,.13);border-color:var(--accent)}\n.set-dot.done .set-num,.set-dot.done .set-reps{color:var(--accent)}\n\n/* 计时器 */\n.timer{background:var(--card2);border:1px solid var(--border);border-radius:12px;\n  padding:13px 14px;display:flex;align-items:center;gap:13px}\n.tm-main{flex:1;min-width:0}\n.tm-disp{display:flex;align-items:baseline;gap:5px;margin-bottom:3px}\n.tm-sec{font-size:29px;font-weight:800;font-variant-numeric:tabular-nums;line-height:1;\n  letter-spacing:-1px}\n.tm-sec.run{color:var(--accent)}\n.tm-sec.fin{color:var(--warn)}\n.tm-unit{font-size:11px;color:var(--muted2);font-weight:600}\n.tm-hint{font-size:10.5px;color:var(--muted2);line-height:1.5;height:16px;overflow:hidden;\n  text-overflow:ellipsis;white-space:nowrap}\n.tm-ctrls{display:flex;flex-direction:column;gap:6px;flex-shrink:0}\n.tm-row{display:flex;gap:6px}\n.tm-btn{border:1px solid var(--border);background:var(--bg2);color:var(--text);\n  border-radius:8px;font-size:11px;font-weight:700;cursor:pointer;transition:all .18s;\n  font-family:inherit}\n.tm-btn:active{transform:scale(.93)}\n.tm-btn:hover{border-color:var(--border2)}\n.tm-adj{width:32px;height:28px}\n.tm-play{width:60px;height:28px;background:rgba(0,224,164,.13);color:var(--accent);\n  border-color:rgba(0,224,164,.3)}\n.tm-play.on{background:rgba(255,159,67,.13);color:var(--warn);border-color:rgba(255,159,67,.3)}\n.tm-reset{width:100%;height:26px;font-size:10.5px;color:var(--muted)}\n\n/* 清单页 */\n.chk{display:flex;align-items:flex-start;gap:11px;padding:11px 0;border-bottom:1px solid var(--border)}\n.chk:last-child{border-bottom:none;padding-bottom:0}\n.chk-b{width:22px;height:22px;border-radius:7px;border:1.5px solid var(--border2);\n  background:var(--bg2);flex-shrink:0;cursor:pointer;display:flex;align-items:center;\n  justify-content:center;transition:all .2s;margin-top:1px}\n.chk-b:active{transform:scale(.88)}\n.chk.done .chk-b{background:var(--accent);border-color:var(--accent)}\n.chk-b svg{width:12px;height:12px;stroke:#0a0e13;stroke-width:3.2;fill:none;opacity:0;transition:opacity .2s}\n.chk.done .chk-b svg{opacity:1}\n.chk-t{flex:1;min-width:0}\n.chk-name{font-size:13.5px;font-weight:600;line-height:1.4}\n.chk.done .chk-name{color:var(--muted2);text-decoration:line-through}\n.chk-det{font-size:11.5px;color:var(--muted);margin-top:2px;line-height:1.5}\n.chk-dose{font-size:11px;color:var(--muted2);font-variant-numeric:tabular-nums;flex-shrink:0;\n  margin-top:2px}\n\n.tip{background:var(--bg2);border-left:2.5px solid var(--accent);border-radius:0 9px 9px 0;\n  padding:10px 13px;font-size:12.5px;color:#c4d0dc;line-height:1.65;margin-top:12px}\n.tip b{color:var(--text);font-weight:700}\n\n/* 完成页 */\n.done-hero{text-align:center;padding:22px 0 18px}\n.done-ico{width:62px;height:62px;border-radius:50%;background:rgba(0,224,164,.13);\n  color:var(--accent);display:flex;align-items:center;justify-content:center;margin:0 auto 14px}\n.done-hero h2{font-size:21px;font-weight:800;margin-bottom:6px}\n.done-hero p{font-size:13px;color:var(--muted)}\n.done-stat{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-bottom:14px}\n\n/* ===== 底部导航 ===== */\n.nav{flex-shrink:0;padding:11px 18px calc(11px + env(safe-area-inset-bottom));\n  border-top:1px solid var(--border);display:flex;align-items:center;gap:12px;\n  background:rgba(10,14,19,.94);backdrop-filter:blur(12px)}\n.nav-btn{flex:0 0 auto;min-width:76px;height:40px;border-radius:10px;border:1px solid var(--border);\n  background:var(--card);color:var(--text);font-size:13px;font-weight:700;cursor:pointer;\n  font-family:inherit;transition:all .18s;display:flex;align-items:center;justify-content:center;gap:5px}\n.nav-btn:active{transform:scale(.95)}\n.nav-btn:hover:not(:disabled){border-color:var(--border2);background:var(--card2)}\n.nav-btn:disabled{opacity:.32;cursor:not-allowed}\n.nav-btn.pri{background:rgba(0,224,164,.13);border-color:rgba(0,224,164,.3);color:var(--accent)}\n.dots{flex:1;display:flex;justify-content:center;gap:6px}\n.dot{width:6px;height:6px;border-radius:50%;background:var(--border2);cursor:pointer;\n  transition:all .25s;flex-shrink:0}\n.dot.on{width:18px;border-radius:3px;background:var(--accent)}\n.dot.seen{background:var(--muted)}\n\n@media(max-width:360px){\n  .specs{gap:6px}\n  .cover-hero h1{font-size:23px}\n  .ex-title h2{font-size:17px}\n  .nav-btn{min-width:66px;font-size:12px}\n}\n</style>\n</head>\n<body>\n<div id=\"app\">\n  <div class=\"topbar\">\n    <div class=\"tb-row\">\n      <div class=\"tb-title\" id=\"headTitle\">综合练背训练计划</div>\n      <div class=\"tb-meta\" id=\"headMeta\">0 / 18 组</div>\n    </div>\n    <div class=\"progress\"><div class=\"progress-fill\" id=\"progFill\"></div></div>\n  </div>\n\n  <div class=\"content\" id=\"content\"></div>\n\n  <div class=\"nav\">\n    <button class=\"nav-btn\" id=\"prevBtn\">&#8249; 上一页</button>\n    <div class=\"dots\" id=\"dots\"></div>\n    <button class=\"nav-btn pri\" id=\"nextBtn\">下一页 &#8250;</button>\n  </div>\n</div>\n\n<script src=\"__PLAN_SCRIPT_1__\"></script>\n</body>\n</html>\n", "练臀训练计划.html": "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover\">\n<title>练臀训练计划</title>\n<style>\n:root{\n  --bg:#0a0e13; --bg2:#111820; --card:#161e27; --card2:#1b242f;\n  --border:#242f3d; --border2:#2e3b4c;\n  --text:#e9eff6; --muted:#8697a8; --muted2:#5f7183;\n  --accent:#00e0a4; --accent2:#00b884;\n  --warn:#ff9f43; --warnbg:rgba(255,159,67,.10);\n  --danger:#ff5f6d; --good:#00e0a4;\n}\n*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}\nhtml,body{height:100%}\nbody{\n  background:var(--bg); color:var(--text);\n  font-family:-apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",sans-serif;\n  font-size:15px; line-height:1.6; overflow:hidden;\n  -webkit-font-smoothing:antialiased;\n}\n#app{display:flex;flex-direction:column;height:100%;max-width:560px;margin:0 auto;\n  background:linear-gradient(170deg,#0a0e13 0%,#111a24 100%);position:relative}\n\n/* ===== 顶栏 ===== */\n.topbar{padding:14px 18px 12px;border-bottom:1px solid var(--border);flex-shrink:0}\n.tb-row{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:9px}\n.tb-title{font-size:16px;font-weight:700;letter-spacing:.3px}\n.tb-meta{font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums}\n.tb-meta b{color:var(--accent);font-weight:700}\n.progress{height:3px;background:var(--border);border-radius:2px;overflow:hidden}\n.progress-fill{height:100%;width:0;background:linear-gradient(90deg,var(--accent2),var(--accent));\n  border-radius:2px;transition:width .35s cubic-bezier(.4,0,.2,1)}\n\n/* ===== 内容区 ===== */\n.content{flex:1;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch;\n  padding:18px 18px 24px;scroll-behavior:smooth}\n.content::-webkit-scrollbar{width:0}\n.page{animation:pageIn .32s cubic-bezier(.4,0,.2,1)}\n@keyframes pageIn{from{opacity:0;transform:translateX(14px)}to{opacity:1;transform:none}}\n\n/* ===== 通用卡片 ===== */\n.card{background:var(--card);border:1px solid var(--border);border-radius:14px;\n  padding:16px;margin-bottom:14px}\n.card-hd{display:flex;align-items:center;gap:10px;margin-bottom:12px}\n.card-ico{width:30px;height:30px;border-radius:9px;display:flex;align-items:center;justify-content:center;\n  font-size:15px;font-weight:700;flex-shrink:0;background:rgba(0,224,164,.13);color:var(--accent)}\n.card-t{font-size:15px;font-weight:700}\n\n.sec-t{font-size:11px;font-weight:700;letter-spacing:1.4px;color:var(--muted2);\n  text-transform:uppercase;margin:16px 0 9px}\n\n/* ===== 封面 ===== */\n.cover-hero{padding:6px 0 18px;text-align:center}\n.cover-hero h1{font-size:26px;font-weight:800;letter-spacing:-.5px;margin-bottom:8px;\n  background:linear-gradient(120deg,#fff 20%,var(--accent));-webkit-background-clip:text;\n  -webkit-text-fill-color:transparent;background-clip:text}\n.cover-hero p{font-size:13px;color:var(--muted);line-height:1.7}\n\n.timebar{display:flex;height:44px;border-radius:11px;overflow:hidden;margin-bottom:9px;\n  border:1px solid var(--border)}\n.tb-seg{display:flex;flex-direction:column;align-items:center;justify-content:center;\n  font-size:11px;line-height:1.25;color:#0a0e13;font-weight:700}\n.tb-seg span{font-size:9px;font-weight:600;opacity:.75}\n.tb-legend{display:flex;gap:14px;justify-content:center;font-size:11px;color:var(--muted);margin-bottom:4px;\n  flex-wrap:wrap}\n.tb-legend i{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:5px;vertical-align:middle}\n\n.kv{display:grid;grid-template-columns:1fr 1fr;gap:9px}\n.kv-item{background:var(--card2);border:1px solid var(--border);border-radius:10px;padding:11px 12px}\n.kv-k{font-size:10px;color:var(--muted2);letter-spacing:.8px;font-weight:700;margin-bottom:3px}\n.kv-v{font-size:15px;font-weight:700;font-variant-numeric:tabular-nums}\n.kv-v small{font-size:11px;color:var(--muted);font-weight:600}\n\n.ov-list{display:flex;flex-direction:column;gap:7px}\n.ov-item{display:flex;align-items:center;gap:11px;background:var(--card2);\n  border:1px solid var(--border);border-radius:10px;padding:10px 12px;cursor:pointer;\n  transition:border-color .2s,transform .15s}\n.ov-item:active{transform:scale(.985)}\n.ov-item:hover{border-color:var(--border2)}\n.ov-n{width:22px;height:22px;border-radius:7px;background:rgba(0,224,164,.13);color:var(--accent);\n  font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.ov-name{flex:1;font-size:13px;font-weight:600}\n.ov-name em{font-style:normal;font-size:10px;color:var(--muted2);font-weight:700;\n  border:1px solid var(--border2);border-radius:4px;padding:0 4px;margin-left:5px}\n.ov-s{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}\n\n/* ===== 动作页 ===== */\n.ex-head{display:flex;align-items:flex-start;gap:12px;margin-bottom:14px}\n.ex-idx{width:38px;height:38px;border-radius:11px;background:rgba(0,224,164,.13);\n  color:var(--accent);display:flex;align-items:center;justify-content:center;\n  font-size:15px;font-weight:800;flex-shrink:0}\n.ex-title{flex:1;min-width:0}\n.ex-title h2{font-size:19px;font-weight:800;letter-spacing:-.3px;line-height:1.3}\n.ex-title h2 em{font-style:normal;font-size:10px;color:var(--muted2);font-weight:700;\n  border:1px solid var(--border2);border-radius:4px;padding:1px 5px;margin-left:6px;vertical-align:middle}\n.ex-en{font-size:11px;color:var(--muted2);letter-spacing:.5px;margin-top:2px}\n.ex-target{font-size:11px;color:var(--accent);margin-top:5px;font-weight:600}\n\n.specs{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:13px}\n.spec{background:var(--card2);border:1px solid var(--border);border-radius:10px;\n  padding:9px 6px;text-align:center}\n.spec-v{font-size:16px;font-weight:800;font-variant-numeric:tabular-nums;line-height:1.2}\n.spec-k{font-size:9.5px;color:var(--muted2);letter-spacing:.7px;font-weight:700;margin-top:3px}\n\n/* 动作示意图 */\n.ex-fig{background:var(--bg2);border:1px solid var(--border);border-radius:12px;\n  padding:6px 6px 2px;margin-bottom:13px;display:flex;justify-content:center}\n.ex-fig svg{width:100%;max-width:320px;height:auto;display:block}\n\n.setup{background:var(--bg2);border:1px solid var(--border);border-radius:10px;\n  padding:11px 13px;margin-bottom:13px;font-size:12.5px;color:#c4d0dc;line-height:1.65}\n.setup b{color:var(--text);font-weight:700}\n\n.steps{margin-bottom:13px}\n.step{display:flex;gap:10px;margin-bottom:8px}\n.step-n{width:20px;height:20px;border-radius:6px;background:var(--border);color:var(--muted);\n  font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;\n  flex-shrink:0;margin-top:1px}\n.step-t{font-size:13px;color:#c4d0dc;line-height:1.6}\n\n/* 注意点 */\n.notes{background:var(--warnbg);border:1px solid rgba(255,159,67,.28);border-radius:12px;\n  padding:13px 14px;margin-bottom:14px}\n.notes-hd{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:800;\n  color:var(--warn);letter-spacing:.8px;margin-bottom:9px}\n.note{display:flex;gap:9px;margin-bottom:7px;font-size:12.5px;line-height:1.6;color:#e2d3c2}\n.note:last-child{margin-bottom:0}\n.note-d{color:var(--warn);font-weight:800;flex-shrink:0;font-size:13px;line-height:1.5}\n.note b{color:#ffc78b;font-weight:700}\n\n/* 提示条 */\n.tip{background:var(--bg2);border-left:2.5px solid var(--accent);border-radius:0 9px 9px 0;\n  padding:10px 13px;font-size:12.5px;color:#c4d0dc;line-height:1.65;margin-top:12px}\n.tip b{color:var(--text);font-weight:700}\n\n/* 组打卡 */\n.sets-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}\n.sets-hd-t{font-size:11px;font-weight:700;letter-spacing:1.2px;color:var(--muted2)}\n.sets-cnt{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}\n.sets{display:flex;gap:9px;margin-bottom:13px}\n.set-dot{flex:1;height:46px;border-radius:11px;background:var(--card2);\n  border:1.5px solid var(--border);display:flex;flex-direction:column;align-items:center;\n  justify-content:center;gap:2px;cursor:pointer;transition:all .2s;position:relative}\n.set-dot:active{transform:scale(.94)}\n.set-num{font-size:13px;font-weight:800;color:var(--muted2);font-variant-numeric:tabular-nums}\n.set-reps{font-size:9.5px;color:var(--muted2);letter-spacing:.3px}\n.set-dot.done{background:rgba(0,224,164,.13);border-color:var(--accent)}\n.set-dot.done .set-num,.set-dot.done .set-reps{color:var(--accent)}\n\n/* 计时器 */\n.timer{background:var(--card2);border:1px solid var(--border);border-radius:12px;\n  padding:13px 14px;display:flex;align-items:center;gap:13px}\n.tm-main{flex:1;min-width:0}\n.tm-disp{display:flex;align-items:baseline;gap:5px;margin-bottom:3px}\n.tm-sec{font-size:29px;font-weight:800;font-variant-numeric:tabular-nums;line-height:1;\n  letter-spacing:-1px}\n.tm-sec.run{color:var(--accent)}\n.tm-sec.fin{color:var(--warn)}\n.tm-unit{font-size:11px;color:var(--muted2);font-weight:600}\n.tm-hint{font-size:10.5px;color:var(--muted2);line-height:1.5;height:16px;overflow:hidden;\n  text-overflow:ellipsis;white-space:nowrap}\n.tm-ctrls{display:flex;flex-direction:column;gap:6px;flex-shrink:0}\n.tm-row{display:flex;gap:6px}\n.tm-btn{border:1px solid var(--border);background:var(--bg2);color:var(--text);\n  border-radius:8px;font-size:11px;font-weight:700;cursor:pointer;transition:all .18s;\n  font-family:inherit}\n.tm-btn:active{transform:scale(.93)}\n.tm-btn:hover{border-color:var(--border2)}\n.tm-adj{width:32px;height:28px}\n.tm-play{width:60px;height:28px;background:rgba(0,224,164,.13);color:var(--accent);\n  border-color:rgba(0,224,164,.3)}\n.tm-play.on{background:rgba(255,159,67,.13);color:var(--warn);border-color:rgba(255,159,67,.3)}\n.tm-reset{width:100%;height:26px;font-size:10.5px;color:var(--muted)}\n\n/* 清单页 */\n.chk{display:flex;align-items:flex-start;gap:11px;padding:11px 0;border-bottom:1px solid var(--border)}\n.chk:last-child{border-bottom:none;padding-bottom:0}\n.chk-b{width:22px;height:22px;border-radius:7px;border:1.5px solid var(--border2);\n  background:var(--bg2);flex-shrink:0;cursor:pointer;display:flex;align-items:center;\n  justify-content:center;transition:all .2s;margin-top:1px}\n.chk-b:active{transform:scale(.88)}\n.chk.done .chk-b{background:var(--accent);border-color:var(--accent)}\n.chk-b svg{width:12px;height:12px;stroke:#0a0e13;stroke-width:3.2;fill:none;opacity:0;transition:opacity .2s}\n.chk.done .chk-b svg{opacity:1}\n.chk-t{flex:1;min-width:0}\n.chk-name{font-size:13.5px;font-weight:600;line-height:1.4}\n.chk.done .chk-name{color:var(--muted2);text-decoration:line-through}\n.chk-det{font-size:11.5px;color:var(--muted);margin-top:2px;line-height:1.5}\n.chk-dose{font-size:11px;color:var(--muted2);font-variant-numeric:tabular-nums;flex-shrink:0;\n  margin-top:2px}\n\n/* 完成页 */\n.done-hero{text-align:center;padding:22px 0 18px}\n.done-ico{width:62px;height:62px;border-radius:50%;background:rgba(0,224,164,.13);\n  color:var(--accent);display:flex;align-items:center;justify-content:center;margin:0 auto 14px}\n.done-hero h2{font-size:21px;font-weight:800;margin-bottom:6px}\n.done-hero p{font-size:13px;color:var(--muted)}\n\n/* ===== 底部导航 ===== */\n.nav{flex-shrink:0;padding:11px 18px calc(11px + env(safe-area-inset-bottom));\n  border-top:1px solid var(--border);display:flex;align-items:center;gap:12px;\n  background:rgba(10,14,19,.94);backdrop-filter:blur(12px)}\n.nav-btn{flex:0 0 auto;min-width:76px;height:40px;border-radius:10px;border:1px solid var(--border);\n  background:var(--card);color:var(--text);font-size:13px;font-weight:700;cursor:pointer;\n  font-family:inherit;transition:all .18s;display:flex;align-items:center;justify-content:center;gap:5px}\n.nav-btn:active{transform:scale(.95)}\n.nav-btn:hover:not(:disabled){border-color:var(--border2);background:var(--card2)}\n.nav-btn:disabled{opacity:.32;cursor:not-allowed}\n.nav-btn.pri{background:rgba(0,224,164,.13);border-color:rgba(0,224,164,.3);color:var(--accent)}\n.dots{flex:1;display:flex;justify-content:center;gap:6px}\n.dot{width:6px;height:6px;border-radius:50%;background:var(--border2);cursor:pointer;\n  transition:all .25s;flex-shrink:0}\n.dot.on{width:18px;border-radius:3px;background:var(--accent)}\n.dot.seen{background:var(--muted)}\n\n@media(max-width:360px){\n  .specs{gap:6px}\n  .cover-hero h1{font-size:23px}\n  .ex-title h2{font-size:17px}\n  .nav-btn{min-width:66px;font-size:12px}\n}\n</style>\n</head>\n<body>\n<div id=\"app\">\n  <div class=\"topbar\">\n    <div class=\"tb-row\">\n      <div class=\"tb-title\" id=\"headTitle\">练臀训练计划</div>\n      <div class=\"tb-meta\" id=\"headMeta\">0 / 18 组</div>\n    </div>\n    <div class=\"progress\"><div class=\"progress-fill\" id=\"progFill\"></div></div>\n  </div>\n\n  <div class=\"content\" id=\"content\"></div>\n\n  <div class=\"nav\">\n    <button class=\"nav-btn\" id=\"prevBtn\">&#8249; 上一页</button>\n    <div class=\"dots\" id=\"dots\"></div>\n    <button class=\"nav-btn pri\" id=\"nextBtn\">下一页 &#8250;</button>\n  </div>\n</div>\n\n<script src=\"__PLAN_SCRIPT_2__\"></script>\n</body>\n</html>\n"};
const css="\n  :root{\n    --bg:#0a0e13; --card:#131a22; --card2:#0f151c; --line:#222e3a;\n    --text:#e8eef5; --muted:#8a97a5; --accent:#00e0a4; --accent2:#4aa8ff;\n    --warn:#ff9f43; --danger:#ff5e6c; --good:#00e0a4;\n    --r:14px;\n  }\n  *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\n  html,body{margin:0;padding:0;background:var(--bg);color:var(--text);\n    font-family:-apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Helvetica Neue\",Arial,sans-serif;\n    -webkit-font-smoothing:antialiased;overscroll-behavior:none}\n  body{max-width:480px;margin:0 auto;min-height:100vh;position:relative;\n    padding-bottom:74px;}\n  .app-head{padding:18px 18px 10px;position:sticky;top:0;z-index:5;\n    background:linear-gradient(180deg,#0a0e13 70%,rgba(10,14,19,0))}\n  .app-head h1{font-size:20px;margin:0;font-weight:800;letter-spacing:.5px}\n  .app-head p{margin:3px 0 0;font-size:12.5px;color:var(--muted)}\n\n  /* 视图 */\n  .view{display:none;padding:4px 14px 16px;animation:fade .28s ease}\n  .view.active{display:block}\n  @keyframes fade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}\n\n  /* 计划卡片 */\n  .plan-card{background:var(--card);border:1px solid var(--line);border-radius:var(--r);\n    padding:16px;margin-bottom:14px;display:flex;gap:14px;align-items:center;\n    cursor:pointer;transition:transform .12s,border-color .15s}\n  .plan-card:active{transform:scale(.985)}\n  .plan-card .pc-ico{width:54px;height:54px;border-radius:14px;flex:0 0 54px;\n    display:flex;align-items:center;justify-content:center;font-size:26px}\n  .plan-card .pc-ico svg{width:28px;height:28px}\n  .tab .ti svg{width:22px;height:22px;display:block}\n  .day .ph svg{width:11px;height:11px;display:inline-block;vertical-align:-1px}\n  .plan-card h3{margin:0 0 4px;font-size:16px;font-weight:700}\n  .plan-card .pc-sub{font-size:12px;color:var(--muted);line-height:1.5}\n  .plan-card .pc-go{margin-left:auto;color:var(--accent);font-size:13px;font-weight:700;\n    display:flex;align-items:center;gap:3px}\n  .plan-card .pc-badge{display:inline-block;margin-top:6px;font-size:10.5px;\n    padding:2px 7px;border-radius:20px;background:rgba(0,224,164,.12);color:var(--accent)}\n\n  /* 日历 */\n  .cal-head{display:flex;align-items:center;justify-content:space-between;\n    padding:6px 4px 12px}\n  .cal-head .cm{font-size:17px;font-weight:800}\n  .cal-nav{display:flex;gap:8px}\n  .cal-nav button{width:34px;height:34px;border-radius:10px;border:1px solid var(--line);\n    background:var(--card);color:var(--text);font-size:18px;line-height:1;cursor:pointer}\n  .cal-nav button:active{background:#1b2530}\n  .week-row,.days-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}\n  .week-row{margin-bottom:6px}\n  .week-row div{text-align:center;font-size:11.5px;color:var(--muted);padding:2px 0}\n  .day{aspect-ratio:1/1;border-radius:11px;background:var(--card2);\n    border:1px solid var(--line);display:flex;flex-direction:column;align-items:center;\n    justify-content:center;position:relative;cursor:pointer;font-size:14px;color:var(--text)}\n  .day.empty{background:transparent;border:none;cursor:default}\n  .day.today{outline:2px solid var(--accent2);outline-offset:-2px}\n  .day.done{background:rgba(0,224,164,.16);border-color:var(--accent);color:var(--accent);font-weight:800}\n  .day .chk{position:absolute;top:3px;right:4px;font-size:11px;line-height:1}\n  .day .ph{position:absolute;bottom:3px;right:4px;font-size:10px;line-height:1}\n  .day .plan-dot{position:absolute;bottom:4px;left:4px;width:5px;height:5px;border-radius:50%;\n    background:var(--warn)}\n  .day.sel{transform:scale(1.04);border-color:var(--accent2)}\n\n  /* 当天详情面板 */\n  .day-panel{margin-top:14px;background:var(--card);border:1px solid var(--line);\n    border-radius:var(--r);padding:16px;display:none}\n  .day-panel.show{display:block;animation:fade .25s}\n  .dp-date{font-size:15px;font-weight:800;margin-bottom:2px}\n  .dp-week{font-size:12px;color:var(--muted);margin-bottom:14px}\n  .dp-row{margin-bottom:16px}\n  .dp-label{font-size:12.5px;color:var(--muted);margin-bottom:8px}\n  .done-btn{width:100%;padding:13px;border-radius:12px;border:1.5px solid var(--accent);\n    background:transparent;color:var(--accent);font-size:15px;font-weight:700;cursor:pointer}\n  .done-btn.on{background:var(--accent);color:#06241c}\n  .plan-chips{display:flex;gap:8px;flex-wrap:wrap}\n  .chip{padding:8px 14px;border-radius:20px;border:1px solid var(--line);\n    background:var(--card2);font-size:13px;color:var(--muted);cursor:pointer}\n  .chip.on{background:rgba(255,159,67,.15);border-color:var(--warn);color:var(--warn);font-weight:700}\n  .photo-box{border:1.5px dashed var(--line);border-radius:12px;padding:14px;\n    text-align:center;cursor:pointer;color:var(--muted);font-size:13px}\n  .photo-box:active{background:#11181f}\n  .photo-prev{position:relative;border-radius:12px;overflow:hidden;display:none}\n  .photo-prev img{width:100%;display:block;border-radius:12px}\n  .photo-prev .del{position:absolute;top:8px;right:8px;background:rgba(0,0,0,.6);\n    color:#fff;border:none;border-radius:50%;width:30px;height:30px;font-size:15px;cursor:pointer}\n  .photo-note{font-size:11px;color:var(--muted);margin-top:6px;line-height:1.5}\n\n  /* 统计 */\n  .stat-big{background:linear-gradient(135deg,#0f2027,#16323a);\n    border:1px solid var(--line);border-radius:var(--r);padding:22px 18px;\n    text-align:center;margin-bottom:14px}\n  .stat-big .num{font-size:46px;font-weight:900;color:var(--accent);line-height:1}\n  .stat-big .lab{font-size:13px;color:var(--muted);margin-top:8px}\n  .stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px}\n  .stat-cell{background:var(--card);border:1px solid var(--line);border-radius:var(--r);\n    padding:14px;text-align:center}\n  .stat-cell .n{font-size:26px;font-weight:800;color:var(--text)}\n  .stat-cell .l{font-size:11.5px;color:var(--muted);margin-top:5px}\n  .stat-cell .n.w{color:var(--warn)} .stat-cell .n.b{color:var(--accent2)}\n  .week7{background:var(--card);border:1px solid var(--line);border-radius:var(--r);\n    padding:16px;margin-bottom:14px}\n  .week7 .wt{font-size:13px;color:var(--muted);margin-bottom:12px}\n  .week7 .row{display:flex;gap:8px}\n  .week7 .c{flex:1;text-align:center}\n  .week7 .c .d{font-size:11px;color:var(--muted);margin-bottom:6px}\n  .week7 .c .dot{width:30px;height:30px;border-radius:50%;margin:0 auto;\n    border:1px solid var(--line);display:flex;align-items:center;justify-content:center;\n    font-size:13px;color:var(--muted)}\n  .week7 .c .dot.on{background:var(--accent);color:#06241c;font-weight:800;border-color:var(--accent)}\n  .plan-stat{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:16px}\n  .plan-stat .pt{font-size:13px;color:var(--muted);margin-bottom:12px}\n  .ps-row{display:flex;align-items:center;gap:10px;margin-bottom:11px}\n  .ps-row .pn{font-size:13px;width:96px;flex:0 0 96px}\n  .ps-bar{flex:1;height:9px;border-radius:6px;background:var(--card2);overflow:hidden}\n  .ps-bar i{display:block;height:100%;background:var(--accent)}\n  .ps-row .pv{font-size:12.5px;color:var(--muted);width:34px;text-align:right}\n  .empty-tip{text-align:center;color:var(--muted);font-size:13px;padding:30px 10px;line-height:1.7}\n\n  /* 底部导航 */\n  .tabbar{position:fixed;bottom:0;left:50%;transform:translateX(-50%);\n    width:100%;max-width:480px;height:64px;background:#0c1219;\n    border-top:1px solid var(--line);display:flex;z-index:20;\n    padding-bottom:env(safe-area-inset-bottom)}\n  .tab{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;\n    gap:3px;color:var(--muted);font-size:11px;cursor:pointer;background:none;border:none}\n  .tab .ti{font-size:21px;line-height:1}\n  .tab.on{color:var(--accent)}\n  .tab.on .ti{transform:translateY(-1px)}\n\n  /* 计划全屏 overlay */\n  .overlay{position:fixed;inset:0;background:#0a0e13;z-index:50;display:none;\n    flex-direction:column}\n  .overlay.show{display:flex}\n  .ov-bar{display:flex;align-items:center;justify-content:space-between;\n    padding:12px 14px;background:#0c1219;border-bottom:1px solid var(--line)}\n  .ov-bar .ot{font-size:15px;font-weight:700}\n  .ov-bar button{background:var(--card);border:1px solid var(--line);color:var(--text);\n    border-radius:10px;padding:7px 14px;font-size:14px;cursor:pointer}\n  .ov-frame{flex:1;border:none;width:100%;background:#0a0e13}\n  .ov-fallback{display:none;padding:30px 20px;text-align:center;color:var(--muted);font-size:14px;line-height:1.8}\n  .ov-fallback a{color:var(--accent)}\n  input[type=file]{display:none}\n  .toast{position:fixed;left:50%;bottom:90px;transform:translateX(-50%);\n    background:rgba(0,0,0,.85);color:#fff;padding:10px 18px;border-radius:22px;\n    font-size:13px;z-index:80;opacity:0;transition:opacity .25s;pointer-events:none;max-width:80%}\n  .toast.show{opacity:1}\n";
const markup="\n\n<div class=\"app-head\">\n  <h1>我的健身打卡</h1>\n  <p>三套计划 · 日历打勾 · 美照记录 · 坚持看得见</p>\n</div>\n\n<!-- 计划视图 -->\n<section class=\"view active\" id=\"view-plans\">\n  <div class=\"plan-card\" data-plan=\"驼背纠正训练计划.html\" data-name=\"驼背纠正计划\">\n    <div class=\"pc-ico\" style=\"background:rgba(74,168,255,.14);color:#4aa8ff\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"4.5\" r=\"2\"/><path d=\"M12 7v6\"/><path d=\"M12 13l-3.2 6M12 13l3.2 6\"/><path d=\"M7.5 9.2L12 11l4.5-1.8\"/></svg></div>\n    <div>\n      <h3>驼背纠正计划</h3>\n      <div class=\"pc-sub\">强化后背链 + 打开胸前链<br>改善圆肩 · 上交叉综合征</div>\n      <span class=\"pc-badge\">约 55 分钟</span>\n    </div>\n    <div class=\"pc-go\">打开 ›</div>\n  </div>\n\n  <div class=\"plan-card\" data-plan=\"综合练背训练计划.html\" data-name=\"综合练背计划\">\n    <div class=\"pc-ico\" style=\"background:rgba(0,224,164,.14);color:#00e0a4\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3v18\"/><path d=\"M7 5.5c0 7 1.4 11.5 5 13.5 3.6-2 5-6.5 5-13.5\"/><path d=\"M7 5.5L12 3l5 2.5\"/></svg></div>\n    <div>\n      <h3>综合练背计划</h3>\n      <div class=\"pc-sub\">练背阔肌宽度 · 显腰细<br>不厚背 · 不粗手臂 · 肩头可练圆</div>\n      <span class=\"pc-badge\">约 58 分钟</span>\n    </div>\n    <div class=\"pc-go\">打开 ›</div>\n  </div>\n\n  <div class=\"plan-card\" data-plan=\"练臀训练计划.html\" data-name=\"练臀计划\">\n    <div class=\"pc-ico\" style=\"background:rgba(255,159,67,.14);color:#ff9f43\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 10.5c-1.6-1.3-5.5-.8-6.7 2.2-.9 2.3.9 4.3 3.4 4.3H12\"/><path d=\"M12 10.5c1.6-1.3 5.5-.8 6.7 2.2.9 2.3-.9 4.3-3.4 4.3H12\"/><path d=\"M12 10.5V8\"/></svg></div>\n    <div>\n      <h3>练臀计划</h3>\n      <div class=\"pc-sub\">臀推 + 倒蹬 + 外展<br>翘而不粗腿 · 含椭圆机有氧</div>\n      <span class=\"pc-badge\">约 65 分钟</span>\n    </div>\n    <div class=\"pc-go\">打开 ›</div>\n  </div>\n\n  <div class=\"photo-note\" style=\"padding:14px 4px 4px;color:var(--muted);font-size:12px;line-height:1.7\">\n    提示：训练完到「日历」里给当天打勾，并上传你的健身美照。在「统计」查看累计健身天数与连续打卡记录。\n  </div>\n</section>\n\n<!-- 日历视图 -->\n<section class=\"view\" id=\"view-calendar\">\n  <div class=\"cal-head\">\n    <div class=\"cm\" id=\"calMonth\">2026年10月</div>\n    <div class=\"cal-nav\">\n      <button id=\"prevM\">‹</button>\n      <button id=\"todayBtn\">今</button>\n      <button id=\"nextM\">›</button>\n    </div>\n  </div>\n  <div class=\"week-row\">\n    <div>日</div><div>一</div><div>二</div><div>三</div><div>四</div><div>五</div><div>六</div>\n  </div>\n  <div class=\"days-grid\" id=\"daysGrid\"></div>\n\n  <div class=\"day-panel\" id=\"dayPanel\">\n    <div class=\"dp-date\" id=\"dpDate\">—</div>\n    <div class=\"dp-week\" id=\"dpWeek\">—</div>\n\n    <div class=\"dp-row\">\n      <div class=\"dp-label\">完成训练打卡</div>\n      <button class=\"done-btn\" id=\"doneBtn\">✓ 标记今天完成训练</button>\n    </div>\n\n    <div class=\"dp-row\">\n      <div class=\"dp-label\">今天练了哪套（可多选）</div>\n      <div class=\"plan-chips\" id=\"planChips\">\n        <div class=\"chip\" data-p=\"posture\">驼背纠正</div>\n        <div class=\"chip\" data-p=\"back\">综合练背</div>\n        <div class=\"chip\" data-p=\"glute\">练臀</div>\n      </div>\n    </div>\n\n    <div class=\"dp-row\">\n      <div class=\"dp-label\">健身打卡美照</div>\n      <div class=\"photo-box\" id=\"photoBox\"><svg viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" style=\"vertical-align:-4px;margin-right:6px\"><path d=\"M4 8h3l1.5-2h7L17 8h3v11H4z\"/><circle cx=\"12\" cy=\"13\" r=\"3.2\"/></svg>点击上传当天健身美照</div>\n      <div class=\"photo-prev\" id=\"photoPrev\">\n        <img id=\"photoImg\" alt=\"健身美照\">\n        <button class=\"del\" id=\"photoDel\">✕</button>\n      </div>\n      <div class=\"photo-note\">照片会压缩后保存在本机，不会上传到任何服务器。</div>\n    </div>\n  </div>\n</section>\n\n<!-- 统计视图 -->\n<section class=\"view\" id=\"view-stats\">\n  <div class=\"stat-big\">\n    <div class=\"num\" id=\"stTotal\">0</div>\n    <div class=\"lab\">累计健身天数</div>\n  </div>\n  <div class=\"stat-grid\">\n    <div class=\"stat-cell\"><div class=\"n b\" id=\"stMonth\">0</div><div class=\"l\">本月打卡</div></div>\n    <div class=\"stat-cell\"><div class=\"n w\" id=\"stStreak\">0</div><div class=\"l\">连续打卡(天)</div></div>\n    <div class=\"stat-cell\"><div class=\"n\" id=\"stLong\">0</div><div class=\"l\">最长连续</div></div>\n    <div class=\"stat-cell\"><div class=\"n\" id=\"stPhoto\">0</div><div class=\"l\">上传美照</div></div>\n  </div>\n  <div class=\"week7\">\n    <div class=\"wt\">近 7 天</div>\n    <div class=\"row\" id=\"week7\"></div>\n  </div>\n  <div class=\"plan-stat\">\n    <div class=\"pt\">各计划打卡次数</div>\n    <div id=\"planStatRows\"></div>\n  </div>\n  <div class=\"empty-tip\" id=\"stEmpty\" style=\"display:none\">\n    还没有打卡记录。<br>去「日历」里给今天打个勾吧 💪\n  </div>\n</section>\n\n<!-- 底部导航 -->\n<nav class=\"tabbar\">\n  <button class=\"tab on\" data-view=\"plans\"><span class=\"ti\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"4\" y=\"3\" width=\"16\" height=\"18\" rx=\"2.5\"/><path d=\"M8 8h8M8 12h8M8 16h5\"/></svg></span>计划</button>\n  <button class=\"tab\" data-view=\"calendar\"><span class=\"ti\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2.5\"/><path d=\"M3 9.5h18M8 3v4M16 3v4\"/></svg></span>日历</button>\n  <button class=\"tab\" data-view=\"stats\"><span class=\"ti\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 20v-6M12 20V6M19 20v-9\"/><path d=\"M3 20h18\"/></svg></span>统计</button>\n</nav>\n\n<!-- 计划全屏 overlay -->\n<div class=\"overlay\" id=\"planOverlay\">\n  <div class=\"ov-bar\">\n    <div class=\"ot\" id=\"ovTitle\">计划</div>\n    <div style=\"display:flex;gap:8px\">\n      <button id=\"ovNew\">新窗口</button>\n      <button id=\"ovClose\">关闭 ✕</button>\n    </div>\n  </div>\n  <iframe class=\"ov-frame\" id=\"ovFrame\"></iframe>\n  <div class=\"ov-fallback\" id=\"ovFallback\">\n    无法直接加载计划页面。<br>请点击此处 <a id=\"ovLink\" href=\"#\" target=\"_blank\">在新窗口打开计划</a>\n  </div>\n</div>\n\n<input type=\"file\" id=\"fileInput\" accept=\"image/*\">\n<div class=\"toast\" id=\"toast\"></div>\n\n";
for (const [i,key] of Object.keys(plans).entries()) plans[key]=plans[key].replace("__PLAN_SCRIPT_"+i+"__",new URL("./plan"+i+".js",import.meta.url).href);
