(function(){
  "use strict";
  var KEY='fitapp_v1';
  var PLANS=[
    {id:'posture',name:'驼背纠正'},
    {id:'back',name:'综合练背'},
    {id:'glute',name:'练臀'}
  ];
  var data=load();
  var vm={y:new Date().getFullYear(), m:new Date().getMonth()};
  var selKey=null; // 当前选中的日期 YYYY-MM-DD

  function load(){
    try{ var s=localStorage.getItem(KEY); if(s) return JSON.parse(s); }catch(e){}
    return {days:{}};
  }
  function save(){
    try{ localStorage.setItem(KEY, JSON.stringify(data)); }
    catch(e){ toast('保存失败：本地存储空间已满，请删除部分照片'); }
  }
  function fmt(d){ // Date -> YYYY-MM-DD
    var y=d.getFullYear(), m=d.getMonth()+1, day=d.getDate();
    return y+'-'+(m<10?'0'+m:m)+'-'+(day<10?'0'+day:day);
  }
  function parse(k){ var p=k.split('-'); return new Date(+p[0],+p[1]-1,+p[2]); }
  function todayKey(){ return fmt(new Date()); }
  function getDay(k){ return data.days[k]||null; }
  function ensureDay(k){ if(!data.days[k]) data.days[k]={done:false,plans:[],photo:''}; return data.days[k]; }

  /* ---------- 导航 ---------- */
  function switchView(id){
    document.querySelectorAll('.view').forEach(function(v){v.classList.remove('active');});
    document.getElementById('view-'+id).classList.add('active');
    document.querySelectorAll('.tab').forEach(function(t){
      t.classList.toggle('on', t.dataset.view===id);
    });
    if(id==='calendar') renderCalendar();
    if(id==='stats') renderStats();
  }
  document.querySelectorAll('.tab').forEach(function(t){
    t.addEventListener('click',function(){ switchView(t.dataset.view); });
  });

  /* ---------- 计划 overlay ---------- */
  var curPlanFile='';
  document.querySelectorAll('.plan-card').forEach(function(c){
    c.addEventListener('click',function(){
      var file=c.dataset.plan, name=c.dataset.name;
      curPlanFile=file;
      document.getElementById('ovTitle').textContent=name;
      var frame=document.getElementById('ovFrame');
      var fb=document.getElementById('ovFallback');
      var link=document.getElementById('ovLink');
      link.href=URL.createObjectURL(new Blob([plans[file]],{type:'text/html'}));
      fb.style.display='none';
      frame.style.display='block';
      frame.srcdoc=plans[file];
      document.getElementById('planOverlay').classList.add('show');
    });
  });
  document.getElementById('ovClose').addEventListener('click',function(){
    var o=document.getElementById('planOverlay');
    o.classList.remove('show');
    document.getElementById('ovFrame').srcdoc='';
  });
  document.getElementById('ovNew').addEventListener('click',function(){
    if(curPlanFile) window.open(URL.createObjectURL(new Blob([plans[curPlanFile]],{type:'text/html'})),'_blank');
  });
  // iframe 加载失败兜底
  document.getElementById('ovFrame').addEventListener('error',function(){
    this.style.display='none';
    document.getElementById('ovFallback').style.display='block';
  });

  /* ---------- 日历 ---------- */
  var WK=['日','一','二','三','四','五','六'];
  function renderCalendar(){
    var y=vm.y, m=vm.m;
    document.getElementById('calMonth').textContent=y+'年'+(m+1)+'月';
    var first=new Date(y,m,1).getDay();
    var total=new Date(y,m+1,0).getDate();
    var tk=todayKey();
    var grid=document.getElementById('daysGrid');
    var html='';
    for(var i=0;i<first;i++) html+='<div class="day empty"></div>';
    for(var d=1;d<=total;d++){
      var k=y+'-'+(m+1<10?'0'+(m+1):(m+1))+'-'+(d<10?'0'+d:d);
      var rec=getDay(k);
      var cls='day';
      if(k===tk) cls+=' today';
      if(rec&&rec.done) cls+=' done';
      if(k===selKey) cls+=' sel';
      var badge='';
      if(rec&&rec.done) badge+='<span class="chk">✓</span>';
      if(rec&&rec.photo) badge+='<span class="ph"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M4 8h3l1.5-2h7L17 8h3v11H4z"/><circle cx="12" cy="13" r="3.2"/></svg></span>';
      if(rec&&rec.plans&&rec.plans.length) badge+='<span class="plan-dot"></span>';
      html+='<div class="'+cls+'" data-k="'+k+'">'+d+badge+'</div>';
    }
    grid.innerHTML=html;
    grid.querySelectorAll('.day:not(.empty)').forEach(function(el){
      el.addEventListener('click',function(){ openDay(el.dataset.k); });
    });
  }
  function openDay(k){
    selKey=k;
    var rec=ensureDay(k);
    var dt=parse(k);
    document.getElementById('dpDate').textContent=k;
    document.getElementById('dpWeek').textContent='星期'+WK[dt.getDay()];
    var db=document.getElementById('doneBtn');
    db.classList.toggle('on', !!rec.done);
    db.textContent= rec.done? '✓ 已完成训练（点击取消）' : '✓ 标记今天完成训练';
    // plan chips
    document.querySelectorAll('#planChips .chip').forEach(function(ch){
      ch.classList.toggle('on', rec.plans.indexOf(ch.dataset.p)>=0);
    });
    // photo
    if(rec.photo){
      document.getElementById('photoImg').src=rec.photo;
      document.getElementById('photoPrev').style.display='block';
      document.getElementById('photoBox').style.display='none';
    }else{
      document.getElementById('photoPrev').style.display='none';
      document.getElementById('photoBox').style.display='block';
    }
    document.getElementById('dayPanel').classList.add('show');
    renderCalendar();
  }
  document.getElementById('prevM').addEventListener('click',function(){
    vm.m--; if(vm.m<0){vm.m=11;vm.y--;} renderCalendar();
  });
  document.getElementById('nextM').addEventListener('click',function(){
    vm.m++; if(vm.m>11){vm.m=0;vm.y++;} renderCalendar();
  });
  document.getElementById('todayBtn').addEventListener('click',function(){
    var n=new Date(); vm.y=n.getFullYear(); vm.m=n.getMonth(); selKey=todayKey();
    renderCalendar(); openDay(todayKey());
  });
  document.getElementById('doneBtn').addEventListener('click',function(){
    if(!selKey) return;
    var rec=ensureDay(selKey);
    rec.done=!rec.done;
    save(); openDay(selKey);
    toast(rec.done?'已打勾 ✓ 今天完成训练':'已取消打勾');
  });
  document.querySelectorAll('#planChips .chip').forEach(function(ch){
    ch.addEventListener('click',function(){
      if(!selKey) return;
      var rec=ensureDay(selKey);
      var p=ch.dataset.p, i=rec.plans.indexOf(p);
      if(i>=0) rec.plans.splice(i,1); else rec.plans.push(p);
      save(); openDay(selKey);
    });
  });

  /* ---------- 照片上传（压缩） ---------- */
  var pendingFile=null;
  document.getElementById('photoBox').addEventListener('click',function(){
    if(!selKey){ toast('请先选择日期'); return; }
    document.getElementById('fileInput').click();
  });
  document.getElementById('fileInput').addEventListener('change',function(e){
    var f=e.target.files&&e.target.files[0];
    if(!f) return;
    compressImage(f,function(dataUrl){
      if(!selKey) return;
      var rec=ensureDay(selKey);
      rec.photo=dataUrl; rec.done=true; // 传了照片默认也算完成
      save(); openDay(selKey);
      toast('美照已保存 📷');
    });
    e.target.value='';
  });
  document.getElementById('photoDel').addEventListener('click',function(){
    if(!selKey) return;
    var rec=ensureDay(selKey);
    rec.photo='';
    save(); openDay(selKey);
    toast('已删除照片');
  });
  function compressImage(file, cb){
    var reader=new FileReader();
    reader.onload=function(ev){
      var img=new Image();
      img.onload=function(){
        var maxW=900, maxH=900;
        var w=img.width, h=img.height;
        if(w>maxW||h>maxH){
          var r=Math.min(maxW/w, maxH/h);
          w=Math.round(w*r); h=Math.round(h*r);
        }
        var cv=document.createElement('canvas');
        cv.width=w; cv.height=h;
        cv.getContext('2d').drawImage(img,0,0,w,h);
        cb(cv.toDataURL('image/jpeg',0.7));
      };
      img.onerror=function(){ toast('图片读取失败'); };
      img.src=ev.target.result;
    };
    reader.readAsDataURL(file);
  }

  /* ---------- 统计 ---------- */
  function doneKeys(){ return Object.keys(data.days).filter(function(k){return data.days[k].done;}).sort(); }
  function dayDiff(a,b){ return Math.round((parse(b)-parse(a))/86400000); }
  function renderStats(){
    var keys=doneKeys();
    var total=keys.length;
    var tk=todayKey();
    var ym=tk.slice(0,7);
    var month=keys.filter(function(k){return k.indexOf(ym)===0;}).length;
    var photos=Object.keys(data.days).filter(function(k){return data.days[k].photo;}).length;
    // 连续打卡（从今天往回）
    var cur=0, d=new Date();
    while(true){ var k=fmt(d); if(data.days[k]&&data.days[k].done){cur++; d.setDate(d.getDate()-1);} else break; }
    // 最长连续
    var longest=0, run=0, prev=null;
    keys.forEach(function(k){
      if(prev && dayDiff(prev,k)===1) run++; else run=1;
      if(run>longest) longest=run;
      prev=k;
    });
    document.getElementById('stTotal').textContent=total;
    document.getElementById('stMonth').textContent=month;
    document.getElementById('stStreak').textContent=cur;
    document.getElementById('stLong').textContent=longest;
    document.getElementById('stPhoto').textContent=photos;
    document.getElementById('stEmpty').style.display = total? 'none':'block';

    // 近7天
    var w7=document.getElementById('week7'); var wh='';
    var base=new Date(); base.setDate(base.getDate()-6);
    for(var i=0;i<7;i++){
      var dd=new Date(base); dd.setDate(base.getDate()+i);
      var k=fmt(dd); var on=data.days[k]&&data.days[k].done;
      wh+='<div class="c"><div class="d">'+(dd.getMonth()+1)+'/'+dd.getDate()+'</div>'+
          '<div class="dot'+(on?' on':'')+'">'+(on?'✓':'·')+'</div></div>';
    }
    w7.innerHTML=wh;

    // 各计划次数
    var cnt={posture:0,back:0,glute:0};
    Object.keys(data.days).forEach(function(k){
      (data.days[k].plans||[]).forEach(function(p){ if(cnt[p]!=null) cnt[p]++; });
    });
    var maxc=Math.max(1,cnt.posture,cnt.back,cnt.glute);
    var rows='';
    PLANS.forEach(function(p){
      var c=cnt[p.id];
      rows+='<div class="ps-row"><div class="pn">'+p.name+'</div>'+
            '<div class="ps-bar"><i style="width:'+(c/maxc*100)+'%"></i></div>'+
            '<div class="pv">'+c+'</div></div>';
    });
    document.getElementById('planStatRows').innerHTML=rows;
  }

  /* ---------- 工具 ---------- */
  var toastT=null;
  function toast(msg){
    var t=document.getElementById('toast');
    t.textContent=msg; t.classList.add('show');
    clearTimeout(toastT);
    toastT=setTimeout(function(){ t.classList.remove('show'); },1800);
  }

  // 初始
  renderCalendar();
})();


