(function(){
  // 注册 Service Worker：实现离线缓存，也是「可安装到桌面」的前提之一
  
  // 添加到桌面引导（仅在未安装时提示一次）
  function isStandalone(){
    return (window.navigator.standalone===true) ||
           (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches);
  }
  function platformSteps(){
    var ua=navigator.userAgent;
    if(/iPhone|iPad|iPod/i.test(ua)){
      return '<b>iPhone / iPad：</b>先打开离线入口，再用 <b>Safari</b> 打开 → 点底部「分享」按钮 → 选「添加到主屏幕」→ 点「添加」即可。';
    }
    if(/Android/i.test(ua)){
      return '<b>安卓手机：</b>先打开离线入口，再用 <b>Chrome</b> 打开 → 点右上「⋮」菜单 → 选「安装应用 / 添加到主屏幕」→ 确认。';
    }
    return '<b>电脑：</b>先打开离线入口，再用 <b>Chrome / Edge</b> 打开 → 地址栏右侧点「安装」图标（或菜单里「安装应用」）→ 确认。';
  }
  try{
    if(!isStandalone() && !localStorage.getItem('fitapp_install_tip')){
      var tip=document.getElementById('installTip');
      document.getElementById('itSteps').innerHTML=platformSteps();
      var a=document.createElement('a'); a.href=new URL('../offline.html',import.meta.url).href; a.textContent='打开离线入口'; a.style.color='var(--accent)'; document.getElementById('itSteps').appendChild(a); tip.removeAttribute('hidden');
      function closeTip(){
        tip.setAttribute('hidden','');
        try{localStorage.setItem('fitapp_install_tip','1');}catch(e){}
      }
      document.getElementById('itClose').addEventListener('click',closeTip);
      document.getElementById('itMask').addEventListener('click',closeTip);
    }
  }catch(e){}
})();

